export type OceanArtKey = KeyOf<typeof OCEAN_ART>;

/** The keys of the one-colour pictures, the ones that take any colour (`MONO`). */
export type OceanMonoKey = {
  [K in OceanArtKey]: (typeof OCEAN_ART)[K] extends { MONO: true } ? K : never;
}[OceanArtKey];

/**
 * What the owner's pool holds, the pictures the pages show. Laura's `MASCOT`
 * assigns them; the Design's tests check the pool against the art.
 * @internal
 */
export const OCEAN_MASCOT_POOL = [
  "OCTOPUS_NOTO",
  "OCTOPUS_FIREFOX",
  "OCTOPUS_CLASSIC",
  "SQUID_NOTO",
  "JELLYFISH_NOTO",
  "OCTOPUS_MONO",
] as const satisfies readonly OceanArtKey[];
